<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Metrics{active_users:number;active_groups:number;messages_today:number;pending_moments:number;calls_today:number}const data=ref<Metrics|null>(null);onMounted(async()=>{data.value=await request<Metrics>('/v1/ops/dashboard')})</script>
<template><div class="page"><h1>工作台</h1><p>核心业务实时概览</p><div class="metrics"><div><span>有效用户</span><strong>{{data?.active_users??'-'}}</strong></div><div><span>活跃群聊</span><strong>{{data?.active_groups??'-'}}</strong></div><div><span>今日消息</span><strong>{{data?.messages_today??'-'}}</strong></div><div><span>待审动态</span><strong>{{data?.pending_moments??'-'}}</strong></div><div><span>今日通话</span><strong>{{data?.calls_today??'-'}}</strong></div></div></div></template>
<style scoped>.page{max-width:1180px}h1{margin:0;font-size:24px}.page>p{color:var(--bim-muted);margin:6px 0 22px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));border:1px solid var(--bim-border);background:#fff}.metrics div{padding:20px;border-right:1px solid var(--bim-border)}.metrics div:last-child{border:0}.metrics span{display:block;color:var(--bim-muted);font-size:13px}.metrics strong{display:block;margin-top:10px;font-size:28px}@media(max-width:700px){.metrics div{border-right:0;border-bottom:1px solid var(--bim-border)}}</style>
